SELECT * FROM plt_credential_grant WHERE tenant_id=#{q.tenantId} AND credential_id=#{q.credentialId}
 AND grantee_type=#{q.granteeType} AND grantee_id=#{q.granteeId}
 AND device_id=#{q.deviceId} AND protocol=#{q.protocol}
 AND (command_template_id='*' OR command_template_id=#{q.commandTemplateId})
 AND status='ACTIVE' AND expires_at > #{q.effectiveAt} AND deleted=b'0'
